const items = $input.all();
const queryMeta = $('Read Query List').first().json;
const baselineMs = parseFloat(queryMeta.baseline_ms) || 100;
const queryName = queryMeta.query_name || 'unknown';

const results = items.map(item => {
  const plan = item.json['QUERY PLAN'] || item.json;
  let executionTime = 0;
  let planningTime = 0;
  let nodeType = 'Unknown';

  if (Array.isArray(plan)) {
    const p = plan[0];
    executionTime = p['Execution Time'] || p.executionTime || 0;
    planningTime = p['Planning Time'] || p.planningTime || 0;
    nodeType = p.Plan ? p.Plan['Node Type'] : 'Unknown';
  } else if (typeof plan === 'object') {
    executionTime = plan['Execution Time'] || plan.executionTime || 0;
    planningTime = plan['Planning Time'] || plan.planningTime || 0;
  }

  const totalTime = executionTime + planningTime;
  const ratio = totalTime / baselineMs;
  const degraded = ratio > 2.0;

  return {
    json: {
      query_name: queryName,
      execution_time_ms: executionTime.toFixed(2),
      planning_time_ms: planningTime.toFixed(2),
      total_time_ms: totalTime.toFixed(2),
      baseline_ms: baselineMs,
      ratio_to_baseline: ratio.toFixed(2),
      node_type: nodeType,
      is_degraded: degraded,
      status: degraded ? 'DEGRADED' : (ratio > 1.5 ? 'WARNING' : 'OK'),
      measured_at: new Date().toISOString()
    }
  };
});

return results;

